def clean(value: str) -> str:
    """Требование оформления применяется к авторскому тексту, а не к цитатам."""
    return value.replace("ё", "е").replace("Ё", "Е").replace(" — ", ". ")


def resolve(path: str, symbol: str | None) -> dict:
    """Ссылка считается проверенной только при наличии файла и нужного символа."""
    text = (ROOT / path).read_text(encoding="utf-8-sig")
    line = 1
    if symbol:
        leaf = symbol.split(".")[-1]
        match = re.search(r"(?:def|class|function)\s+" + re.escape(leaf) + r"\b", text)
        if not match:
            raise ValueError(f"Символ не найден: {path}: {symbol}")
        line = text[:match.start()].count("\n") + 1
    return {"path": path, "symbol": symbol, "line": line}


labs = []
for number in range(7, 13):
    source = ROOT / f"docs/course/lab{number}.txt"
    raw = source.read_text(encoding="utf-8-sig")
    demo = raw.split("Что демонстрирует студент", 1)[1].split("Критерии оценивания", 1)[0].strip()
    questions = []
    for index, (former, detail) in enumerate(zip(old[number]["qa"], DETAILS[number], strict=True), 1):
        answer, path, symbol, implementation, oral, demonstration, mistake = detail
        questions.append({
            "id": f"L{number}-A{index:02}", "kind": "Авторский учебный вопрос из прежнего сборника",
            "question": clean(former[0]), "answer": clean(answer),
            "implementation": clean(implementation), "code": resolve(path, symbol),
            "oral": clean(oral), "demo": clean(demonstration), "mistake": clean(mistake),
        })
    labs.append({
        "number": number, "title": clean(old[number]["title"]), "theory": clean(THEORY[number]),
        "source": source.relative_to(ROOT).as_posix(),
        "source_sha256": hashlib.sha256(source.read_bytes()).hexdigest(),
        "official_demo": demo, "questions": questions,
    })

